mapper.update:
UPDATE dogs
SET name = #{name},
    updated_at = CASE
        WHEN status = 'exploring' AND explore_duration_hours IS NULL THEN updated_at
        ELSE #{updatedAt}
    END
WHERE id = #{id}
  AND owner_id = #{ownerId}

UPDATE dogs
SET bond = #{bond},
    energy = #{energy},
    updated_at = CASE
        WHEN status = 'exploring' AND explore_duration_hours IS NULL THEN updated_at
        ELSE #{updatedAt}
    END
WHERE id = #{id}
  AND owner_id = #{ownerId}

UPDATE dogs
SET stage = #{stage},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND owner_id = #{ownerId}
  AND stage != #{stage}

UPDATE dogs
SET race_count = race_count + 1,
    race_first_count = race_first_count + #{firstPlaceIncrement},
    weekly_points = weekly_points + #{weeklyPoints},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND owner_id = #{ownerId}

UPDATE dogs
SET energy = energy - #{energyCost},
    status = 'exploring',
    explore_location = #{location},
    explore_ends_at = #{exploreEndsAt},
    explore_duration_hours = #{durationHours},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND owner_id = #{ownerId}
  AND status = 'idle'
  AND energy >= #{energyCost}

UPDATE dogs
SET status = 'idle',
    explore_location = NULL,
    explore_ends_at = NULL,
    explore_duration_hours = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND owner_id = #{ownerId}
  AND status = 'exploring'

UPDATE dogs
SET status = 'idle',
    explore_location = NULL,
    explore_ends_at = NULL,
    explore_duration_hours = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND owner_id = #{ownerId}
  AND status = 'exploring'

UPDATE dogs
SET explore_ends_at = #{exploreEndsAt},
    explore_duration_hours = CASE
        WHEN explore_duration_hours IS NULL THEN #{durationHours}
        ELSE explore_duration_hours
    END,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND owner_id = #{ownerId}
  AND status = 'exploring'
  AND explore_ends_at IS NOT NULL
  AND explore_ends_at > #{exploreEndsAt}
